import random
random.seed(5)

def prop_reverse_twice(xs):
    return list(reversed(list(reversed(xs)))) == xs

def gen_list():
    return [random.randint(-9, 9) for _ in range(random.randint(0, 8))]

fails = 0
for _ in range(300):
    if not prop_reverse_twice(gen_list()):
        fails += 1
print('300 random cases, failures:', fails)
# shrinking: on failure, minimize the input automatically (frameworks do this)
print('property: reverse(reverse(x)) == x  (no examples written by hand)')

import random
random.seed(11)

def parse_int(s):  # target with a latent bug
    if s.startswith('0x'):
        return int(s, 16)
    return int(s)

corpus = ['42', '0x2a', '-7']
crashes = []
for _ in range(2000):
    seed = random.choice(corpus)
    data = ''.join(random.choice('0123456789x-abcdef') for _ in range(random.randint(1, 6)))
    try:
        parse_int(data if random.random() < 0.5 else seed)
    except ValueError:
        pass  # expected
    except Exception as e:
        crashes.append((data, type(e).__name__))
print('2000 fuzz cases, unexpected crashes:', len(crashes))
print('coverage guidance (AFL++) aims mutations at undiscovered paths')

# mutants of: def discount(p): return p*0.9 if p>100 else p
def original(p):
    return p * 0.9 if p > 100 else p

mutants = [
    ('flip > to >=', lambda p: p * 0.9 if p >= 100 else p),
    ('drop discount', lambda p: p),
    ('0.9 -> 0.8', lambda p: p * 0.8 if p > 100 else p),
]
tests = [(50, 50), (200, 180), (100, 100)]  # (input, expected)

def kills(m):
    return any(m(p) != want for p, want in tests)

for name, m in mutants:
    print('%-14s %s' % (name, 'KILLED' if kills(m) else 'SURVIVED (test hole!)'))
print('mutation score: killed/total = the honest coverage number')

# greedy coverage: keep inputs that cover new branches
def target(x):
    if x < 0:
        return 'neg'
    elif x == 0:
        return 'zero'
    elif x > 100:
        return 'big'
    return 'small'

import random
random.seed(8)
covered, suite = set(), []
for _ in range(500):
    x = random.randint(-10, 110)
    branch = target(x)
    if branch not in covered:
        covered.add(branch)
        suite.append(x)
print('branches covered:', sorted(covered))
print('minimal suite:', sorted(suite), '(kept only inputs hitting NEW branches)')

# the discipline: reproduce FIRST (fails), then fix (passes), keep forever
def total_buggy(xs):
    s = 0
    for x in xs[1:]:  # BUG: skips the first element (issue #418)
        s += x
    return s

def total_fixed(xs):
    return sum(xs)

regression_test = ([1, 2, 3], 6)  # issue #418: never silently return
xs, want = regression_test
print('buggy :', total_buggy(xs) == want, '(test catches it)')
print('fixed :', total_fixed(xs) == want, '(test guards it forever)')
print('tag: issue #418. A bug without a regression test WILL return.')

# honest metric: generated tests must FAIL on buggy, PASS on fixed
def buggy(xs):
    return sum(xs[1:])  # the bug

def fixed(xs):
    return sum(xs)

# 'generated' tests (simulated)
gen_tests = [([1, 2, 3], 6), ([], 0), ([5], 5)]
catches = sum(1 for xs, want in gen_tests if buggy(xs) != want and fixed(xs) == want)
print('generated tests catching the real bug: %d/%d' % (catches, len(gen_tests)))
print('pretty tests catching nothing = decoration; catch rate = the metric')
